const config = $('⚙️ Config Growth54').item.json;
const empresaRaw = $('📊 Obtener Perfil Empresa').item?.json || {};
const estRaw = $('🎯 Obtener Estrategia G54').item?.json || {};
const postsRaw = $('📝 Obtener Posts Publicados G54').item?.json || {};
const leadsRaw = $('💼 Obtener Leads G54').item?.json || {};
const metricasRaw = $('📈 Obtener Métricas G54').item?.json || {};
let fbInsights = {};
try { fbInsights = $('📊 Meta API: FB Account Insights').item?.json || {}; } catch(e) {}
let igInsights = {};
try { igInsights = $('📊 Meta API: IG Account Insights').item?.json || {}; } catch(e) {}
let ideasRaw = {};
try { ideasRaw = $('🔍 Obtener Ideas Descartadas G54').item?.json || {}; } catch(e) {}

const empresa = empresaRaw.data || {};
const estrategia = estRaw.data || {};
const postsAll = postsRaw.data || [];
const leads = leadsRaw.data || [];
const metricas = metricasRaw.data || [];
const ideasTodas = ideasRaw.data || [];

// FB account-level metrics (array de {name, values:[{value, end_time}]})
const fbAccountMetrics = fbInsights.data || [];

// IG account-level metrics
const igAccountMetrics = igInsights.data || [];

function sumMetric(metrics, name) {
  const m = metrics.find(x => x.name === name);
  if (!m) return 0;
  if (m.total_value) return m.total_value.value || 0;
  if (!m.values) return 0;
  return m.values.reduce((s, v) => {
    const val = v.value || 0;
    return s + (typeof val === 'object' ? Object.values(val).reduce((a, b) => a + b, 0) : val);
  }, 0);
}

const fechaInicioUnix = Number(config.FECHA_INICIO_UNIX) || Math.floor((Date.now() - 30*24*60*60*1000)/1000);
const fechaFinUnix = Number(config.FECHA_FIN_UNIX) || Math.floor(Date.now()/1000);

// Leads stats — leídos de GET /api/whatsapp/conversations (sesión), no del endpoint viejo
// GET /api/n8n/companies/{id}/wa/leads, que exige un ?phone= puntual y por eso siempre
// devolvía 422 sin datos cuando se le pedía la lista completa — la "Generación de Demanda"
// mostraba 0 siempre, no porque no hubiera actividad, sino porque la llamada nunca funcionó.
// Cada conversación real viene con { created_at, contact: { estado, origen } }.
const leadsPeriodo = leads.filter(l => {
  if (!l.created_at) return false;
  const t = Math.floor(new Date(l.created_at).getTime() / 1000);
  return t >= fechaInicioUnix && t <= fechaFinUnix;
});
const estadoDe = (l) => ((l.contact && l.contact.estado) || '').toLowerCase();
const origenDe = (l) => (l.contact && l.contact.origen) || 'desconocido';

const totalLeads = leadsPeriodo.length;
const leadsCalientes = leadsPeriodo.filter(l => /caliente|hot/.test(estadoDe(l))).length;
const leadsTibios = leadsPeriodo.filter(l => /tibio|warm/.test(estadoDe(l))).length;
const leadsPorOrigen = leadsPeriodo.reduce((acc, l) => {
  const o = origenDe(l);
  acc[o] = (acc[o] || 0) + 1;
  return acc;
}, {});

// KPI #4 — Supervisión de IA: cuántas veces el bot escaló correctamente en vez de
// improvisar una respuesta (dato real: datos_calificacion.escalada_enviada, el mismo
// campo que ya usa Marco/SW03 para marcar cuándo pasó a un especialista). Es un
// indicador DISTINTO de "error corregido" — acá la IA reconoció su propio límite,
// no es que un humano haya tenido que arreglar algo que salió mal.
const escaladasCorrectas = leadsPeriodo.filter(l => {
  const dc = (l.contact && l.contact.datos_calificacion) || {};
  return dc.escalada_enviada === true;
}).length;

// KPI #4 — Supervisión de IA: ideas que un humano descartó explícitamente en el panel
// (status=descartado). Es una corrección real y medible: la IA propuso, una persona
// dijo que no. Filtrado al período real del reporte por fecha de actualización
// (el momento del descarte), no de creación.
const ideasDescartadasPeriodo = ideasTodas.filter(i => {
  if (i.status !== 'descartado') return false;
  if (!i.updated_at) return false;
  const t = Math.floor(new Date(i.updated_at).getTime() / 1000);
  return t >= fechaInicioUnix && t <= fechaFinUnix;
});
const ideasDescartadas = ideasDescartadasPeriodo.length;

// KPI #3 — Tiempo real de respuesta a clientes: para cada conversación real del
// período, busca el primer mensaje del cliente seguido por la primera respuesta del
// bot, y mide la diferencia real en minutos entre ambos timestamps (sent_at real de
// Meta/WhatsApp, no un dato inventado). Se promedian todas las conversaciones que
// tuvieron al menos un par user→bot real — las que quedaron sin respuesta (escaladas,
// o simplemente no contestadas) no entran en el promedio, pero si eso es relevante ya
// se refleja aparte en escaladasCorrectas / leads sin clasificar.
const tiemposRespuestaMin = [];
for (const l of leadsPeriodo) {
  const msgs = (l.messages || []).slice().sort((a, b) => new Date(a.sent_at) - new Date(b.sent_at));
  for (let i = 0; i < msgs.length; i++) {
    if (msgs[i].rol !== 'user') continue;
    const respuesta = msgs.slice(i + 1).find(m => m.rol === 'bot');
    if (!respuesta) continue;
    const diffMin = (new Date(respuesta.sent_at) - new Date(msgs[i].sent_at)) / 60000;
    if (diffMin >= 0 && diffMin < 1440) tiemposRespuestaMin.push(diffMin); // descarta outliers >24h (huecos reales de conversación, no latencia)
    break; // solo el primer par user→bot de cada conversación — el tiempo de "primera respuesta"
  }
}
const tiempoRespuestaPromedioMin = tiemposRespuestaMin.length > 0
  ? Math.round((tiemposRespuestaMin.reduce((a, b) => a + b, 0) / tiemposRespuestaMin.length) * 10) / 10
  : null;
const tiempoRespuestaMuestra = tiemposRespuestaMin.length;

// Posts stats from G54 — filtrados al período real del reporte. Antes se contaban
// TODOS los posts "publicado" que existieran (limit=20, sin filtro de fecha), así que
// "Total posts publicados" mezclaba actividad de meses anteriores con la del período
// que el reporte dice estar analizando.
const postsPeriodo = postsAll.filter(p => {
  if (p.status !== 'publicado') return false;
  if (!p.fecha_publicada) return false;
  const t = Math.floor(new Date(p.fecha_publicada).getTime() / 1000);
  return t >= fechaInicioUnix && t <= fechaFinUnix;
});
const totalPosts = postsPeriodo.length;
const postsPorPlataforma = postsPeriodo.reduce((acc, p) => {
  const pl = p.platform || 'sin_plataforma';
  acc[pl] = (acc[pl] || 0) + 1;
  return acc;
}, {});

// Backlog real — hecho operativo, no una recomendación de IA: si la consistencia
// quedó por debajo de lo comprometido, esto explica una causa posible y verificable
// (hay contenido listo que no salió) sin opinar ni sugerir nada. Decisión explícita
// de la usuaria: solo hechos operativos, no consejos (no reabre el ítem 194).
const postsAprobadosSinProgramar = postsAll.filter(p => p.status === 'aprobado').length;
const postsBorrador = postsAll.filter(p => p.status === 'borrador').length;

// Posts comprometidos según la estrategia — parsea 'Facebook 2x/sem, Instagram 1x/sem'
// (mismo patrón real ya usado en Ideas AI, ítem 121) y lo multiplica por las semanas
// reales del período — sin esto, "consistencia" no tenía con qué compararse.
function parsearFrecuencia(frecuenciaStr) {
  const resultado = {};
  const regex = /([A-Za-zÀ-ÿ]+)\s*(\d+)\s*x\s*\/?\s*sem/gi;
  let match;
  while ((match = regex.exec(frecuenciaStr || '')) !== null) {
    resultado[match[1]] = parseInt(match[2], 10);
  }
  return resultado;
}
const semanasPeriodo = Math.max(1, (fechaFinUnix - fechaInicioUnix) / (7*24*60*60));
const frecuenciaPorPlataforma = parsearFrecuencia(estrategia.frecuencia);
const postsComprometidos = Object.keys(frecuenciaPorPlataforma).reduce((acc, plat) => {
  acc[plat] = Math.round(frecuenciaPorPlataforma[plat] * semanasPeriodo);
  return acc;
}, {});
const totalComprometidos = Object.values(postsComprometidos).reduce((a,b)=>a+b, 0);

// FB account-level summary (corrected — no longer per-post)
const fbVistasPerfil = sumMetric(fbAccountMetrics, 'page_views_total');
const fbInteracciones = sumMetric(fbAccountMetrics, 'page_post_engagements');
const fbNuevosFans = sumMetric(fbAccountMetrics, 'page_daily_follows_unique');
const fbReacciones = sumMetric(fbAccountMetrics, 'page_actions_post_reactions_total');

const fbTieneDatos = fbAccountMetrics.length > 0;

// IG account-level summary
// 'impressions' NO se pide a Meta desde el fix del ítem 148 (incompatible con
// metric_type=total_value en cuentas IG) — nunca se calcula acá para no reportarle
// a la IA un "Impresiones: 0" falso que ni siquiera intentamos medir.
const igAlcance = sumMetric(igAccountMetrics, 'reach');
const igCuentasActivas = sumMetric(igAccountMetrics, 'accounts_engaged');
const igVistasPerfil = sumMetric(igAccountMetrics, 'profile_views');
const igClicksWeb = sumMetric(igAccountMetrics, 'website_clicks');
const igTieneDatos = igAccountMetrics.length > 0;

// Métricas históricas de G54 — corregido el shape real de /api/rrss/metricas
// (platform, alcance_total, engagement_total, clics_total, leads_total), antes
// leía m.reach/m.engagement/m.clicks — campos que nunca existieron en la respuesta
// real, así que este resumen le mandaba 0 a la IA en cada corrida sin importar
// los datos reales, incluso después de que el ítem 184 corrigiera la escritura.
const metricasResumen = metricas.slice(0, 10).map(m => ({
  plataforma: m.platform || '',
  alcance: m.alcance_total || 0,
  engagement: m.engagement_total || 0,
  clics: m.clics_total || 0,
  leads: m.leads_total || 0
}));

// KPIs from strategy
const kpis = estrategia.kpis || [];
const objetivo = estrategia.objetivo || '';
const audiencia = estrategia.audiencia || '';
const pilares = estrategia.pilares || [];

const periodoAnalisis = config.DIAS_ANALISIS || 30;
const periodoLabel = config.PERIODO_LABEL || '';
const nombreEmpresa = empresa.name || 'la empresa';

const contextoAnalytics = `EMPRESA: ${nombreEmpresa}
OBJETIVO ESTRATÉGICO: ${objetivo}
AUDIENCIA: ${audiencia}
PILARES DE CONTENIDO: ${Array.isArray(pilares) ? pilares.join(', ') : pilares}
KPIs DEFINIDOS: ${Array.isArray(kpis) ? kpis.join(', ') : kpis}
PERÍODO: últimos ${periodoAnalisis} días

--- DATOS DE CONTENIDO (G54), SOLO DEL PERÍODO ---
Total posts publicados en el período: ${totalPosts}
Distribución por plataforma: ${JSON.stringify(postsPorPlataforma)}
Posts comprometidos según estrategia (frecuencia × semanas del período): ${JSON.stringify(postsComprometidos)} (total: ${totalComprometidos})

--- MÉTRICAS FACEBOOK (últimos 30 días, account-level) ---
${fbTieneDatos ? `Visitas al perfil: ${fbVistasPerfil}
Interacciones con posts: ${fbInteracciones}
Fans nuevos: ${fbNuevosFans}
Reacciones totales: ${fbReacciones}` : 'Sin datos de Facebook disponibles'}

--- MÉTRICAS INSTAGRAM (últimos 30 días, account-level) ---
${igTieneDatos ? `Alcance: ${igAlcance}
Cuentas activas: ${igCuentasActivas}
Vistas al perfil: ${igVistasPerfil}
Clics a web: ${igClicksWeb}` : 'Sin datos de Instagram (permiso instagram_manage_insights requerido)'}

--- MÉTRICAS HISTÓRICAS G54 ---
${metricasResumen.length > 0 ? JSON.stringify(metricasResumen, null, 2) : 'Sin métricas guardadas aún'}

--- DATOS DE CONVERSIÓN (G54) ---
Total leads período: ${totalLeads}
Leads calientes: ${leadsCalientes}
Leads tibios: ${leadsTibios}
Leads por origen: ${JSON.stringify(leadsPorOrigen)}
Tasa de calificación: ${totalLeads > 0 ? Math.round((leadsCalientes / totalLeads) * 100) : 0}%
Tiempo promedio de primera respuesta: ${tiempoRespuestaPromedioMin !== null ? tiempoRespuestaPromedioMin + ' minutos (sobre ' + tiempoRespuestaMuestra + ' conversaciones)' : 'sin datos suficientes'}

--- SUPERVISIÓN DE IA (KPI de calidad, no de vanidad) ---
Ideas descartadas por un humano en el panel: ${ideasDescartadas}
Conversaciones escaladas correctamente a un especialista (la IA reconoció su límite): ${escaladasCorrectas}`;

return [{ json: {
  contextoAnalytics,
  nombreEmpresa,
  emailEmpresa: (empresa.emails || [])[0] || '',
  totalPosts,
  postsPorPlataforma,
  postsComprometidos,
  totalComprometidos,
  postsAprobadosSinProgramar,
  postsBorrador,
  totalLeads,
  leadsCalientes,
  leadsTibios,
  leadsPorOrigen,
  periodoAnalisis,
  periodoLabel,
  tiempoRespuestaPromedioMin,
  tiempoRespuestaMuestra,
  ideasDescartadas,
  escaladasCorrectas
}}];

const groqRaw = $('🤖 Groq: Analytics AI').item.json;
const texto = groqRaw.choices?.[0]?.message?.content || '';

const get = (label) => {
  const regex = new RegExp(`(?:^|\\n)\\*{0,2}\\s*${label}\\s*\\*{0,2}[:\\s]+([\\s\\S]*?)(?=\\n\\*{0,2}[A-ZÁÉÍÓÚ][A-ZÁÉÍÓÚ\\s]+\\*{0,2}:|$)`, 'i');
  const match = texto.match(regex);
  let content = (match?.[1] || '').trim();
  if (/^\*{0,2}[A-ZÁÉÍÓÚ][A-ZÁÉÍÓÚ\s]{2,40}\*{0,2}:/.test(content)) return '';
  return content;
};

const reporte = get('REPORTE');
const topContenido = get('TOP CONTENIDO');
const bajoRendimiento = get('BAJO RENDIMIENTO');
const insightsSEO = get('INSIGHTS SEO');
const insightsAEO = get('INSIGHTS AEO');
const insightsGEO = get('INSIGHTS GEO');
const insightsConversion = get('INSIGHTS CONVERSI[ÓO]N');
const recomendaciones = get('RECOMENDACIONES');

const datos = $('🔧 Preparar Datos Analytics').item.json;

return [{ json: {
  reporte,
  topContenido,
  bajoRendimiento,
  insightsSEO,
  insightsAEO,
  insightsGEO,
  insightsConversion,
  recomendaciones,
  texto_completo: texto,
  nombreEmpresa: datos.nombreEmpresa,
  emailEmpresa: datos.emailEmpresa,
  totalPosts: datos.totalPosts,
  totalLeads: datos.totalLeads,
  leadsCalientes: datos.leadsCalientes,
  leadsTibios: datos.leadsTibios,
  leadsPorOrigen: datos.leadsPorOrigen,
  periodoAnalisis: datos.periodoAnalisis,
  periodoLabel: datos.periodoLabel
}}];

const reporte = $('🔍 Parsear Reporte Analytics').item.json;
const config  = $('⚙️ Config Growth54').item.json;
const datos   = $('🔧 Preparar Datos Analytics').item.json;

function sumMetric(raw, name) {
  const m = (raw||[]).find(x=>x.name===name);
  if(!m||!m.values) return 0;
  return m.values.reduce((s,v)=>{ const val=v.value||0; return s+(typeof val==='object'?Object.values(val).reduce((a,b)=>a+b,0):val); },0);
}

let fbRaw = [], igRaw = [];
try { fbRaw = $('📊 Meta API: FB Account Insights').item?.json?.data || []; } catch(e) {}
try { igRaw = $('📊 Meta API: IG Account Insights').item?.json?.data || []; } catch(e) {}

const dateFrom = new Date(Date.now() - 30*24*60*60*1000).toISOString().split('T')[0];
const dateTo   = new Date().toISOString().split('T')[0];

// Facebook — hoy Meta solo entrega page_post_engagements a nivel de cuenta
// como una métrica real de engagement. No hay ninguna métrica de alcance,
// impresiones ni clics en el set que pedimos — antes este nodo llenaba esos
// 3 campos duplicando otros valores (impresiones = alcance, clics = engagement),
// dando la apariencia de datos reales sin serlo. A pedido explícito de la
// usuaria, se deja en 0 lo que genuinamente no medimos, sin aproximar.
const fbEng = sumMetric(fbRaw, 'page_post_engagements');
const fbEngRate = 0; // sin un alcance real de base, no hay tasa que tenga sentido calcular

// Instagram — reach/accounts_engaged/website_clicks sí son métricas reales
// que pedimos. 'impressions' no se pide desde el fix del ítem 148 (incompatible
// con metric_type=total_value en cuentas IG), se deja en 0 en vez de fingir.
const igReach = sumMetric(igRaw, 'reach');
const igEng   = sumMetric(igRaw, 'accounts_engaged');
const igClics = sumMetric(igRaw, 'website_clicks');
// Resguardo de muestra chica, mismo criterio ya usado en el reporte HTML —
// con muy poco alcance real, engagement/alcance puede superar el 100% y no
// tiene sentido persistir esa distorsión en la base de datos.
const igEngRate = igReach >= 10 ? parseFloat(((igEng/igReach)*100).toFixed(2)) : 0;

return [{ json: {
  company_id: parseInt(config.G54_COMPANY_ID) || 1,
  period_from: dateFrom,
  period_to: dateTo,
  facebook: {
    platform: 'facebook',
    alcance_total: 0,
    impresiones_total: 0,
    engagement_total: fbEng,
    engagement_rate_avg: fbEngRate,
    clics_total: 0,
    leads_total: datos.totalLeads || 0
  },
  instagram: {
    platform: 'instagram',
    alcance_total: igReach,
    impresiones_total: 0,
    engagement_total: igEng,
    engagement_rate_avg: igEngRate,
    clics_total: igClics,
    leads_total: 0
  }
}}];

const empresa = $('📊 Obtener Perfil Empresa').first().json;
const cfgPageCheck = $('⚙️ Config Growth54').first().json;
const sinPaginaResuelta = !cfgPageCheck.FB_PAGE_ID && !cfgPageCheck.IG_USER_ID;
const pageWarningHtml = sinPaginaResuelta ? `<tr><td style="background:#fef2f2;border:1px solid #fecaca;border-top:none;padding:14px 28px;"><div style="font-size:12px;color:#991b1b;font-weight:700;">\u26a0\ufe0f No se pudo resolver ninguna p\u00e1gina de Meta conectada para esta empresa.</div><div style="font-size:11px;color:#b91c1c;margin-top:4px;">Los n\u00fameros de este reporte pueden estar incompletos o en cero \u2014 no reflejan necesariamente el desempe\u00f1o real. Verific\u00e1 la conexi\u00f3n de Facebook/Instagram de esta empresa antes de compartirlo.</div></td></tr>` : '';
const estrategia = $('🎯 Obtener Estrategia G54').first().json;
const reporte = $('🔍 Parsear Reporte Analytics').first().json;
const lbData = $('🔧 Línea Base: Buscar y Leer').first()?.json || {};
const lineaBase = lbData.lineaBase || null;
const lineaBaseEvento = lbData.lineaBaseEvento || null;
const metricasHoy = $('📊 Preparar Métricas G54').first().json;
const hoyProgreso = {
  leads: reporte.totalLeads || 0,
  engagement: (metricasHoy.facebook.engagement_total || 0) + (metricasHoy.instagram.engagement_total || 0),
  deals: lbData.dealsHoy || 0,
  ventasCerradas: lbData.ventasCerradasHoy || 0,
};
const ventasPorCanalHoy = lbData.ventasPorCanalHoy || {};
const hitosArranque = lbData.hitos || null;
const clientesConVentaReal = lbData.clientesConVentaReal || 0;
const clientesRecurrentes = lbData.clientesRecurrentes || 0;
const ltvPromedio = lbData.ltvPromedio;
const tokens = $('🔑 Obtener Tokens Sociales G64').first().json;
const datosAnalytics = (() => { try { return $('🔧 Preparar Datos Analytics').first().json || {}; } catch(e){ return {}; } })();
const metricasHistoricas = (() => { try { return $('📈 Obtener Métricas G54').first().json.data || []; } catch(e){ return []; } })();

const fbRaw = (() => { try { return $('📊 Meta API: FB Account Insights').first().json.data || []; } catch(e){ return []; } })();
const igRaw = (() => { try { return $('📊 Meta API: IG Account Insights').first().json.data || []; } catch(e){ return []; } })();
const igChartRaw = (() => { try { return $('📊 Meta API: IG Reach Diario (Chart)').first().json.data || []; } catch(e){ return []; } })();
const weeklyRaw = (() => { try { return $('📊 G54: Métricas por Semana').first().json || {}; } catch(e){ return {}; } })();
const fbFanRaw = (() => { try { return $('📊 Meta API: FB Fan Count').first().json || {}; } catch(e){ return {}; } })();
const igFollowersRaw = (() => { try { return $('📊 Meta API: IG Followers Count').first().json || {}; } catch(e){ return {}; } })();
const fbPostsAll = (() => { try { return ($('📰 Meta: Posts Recientes FB').first().json.data || []).map(p=>({...p,plat:'fb'})); } catch(e){ return []; } })();
const igPostsAll = (() => { try { return ($('📰 Meta: Posts Recientes IG').first().json.data || []).map(p=>({...p,plat:'ig'})); } catch(e){ return []; } })();

const recentPosts = [...fbPostsAll, ...igPostsAll].sort((a,b)=>{
  const da = new Date(a.created_time||a.timestamp||0);
  const db = new Date(b.created_time||b.timestamp||0);
  return db-da;
}).slice(0,3);

function sum(raw, name) {
  const m = raw.find(x=>x.name===name);
  if(!m) return null;
  if(m.total_value) return m.total_value.value||0;
  if(!m.values) return null;
  return m.values.reduce((s,v)=>{ const val=v.value||0; return s+(typeof val==='object'?Object.values(val).reduce((a,b)=>a+b,0):val); },0);
}
function last(raw, name) {
  const m = raw.find(x=>x.name===name);
  if(!m||!m.values||!m.values.length) return null;
  return m.values[m.values.length-1].value||0;
}
function halfTrend(raw, name) {
  const m = raw.find(x=>x.name===name);
  if(!m||!m.values||m.values.length<4) return null;
  const vals = m.values.map(v=>v.value||0);
  const mid = Math.floor(vals.length/2);
  const first = vals.slice(0,mid).reduce((a,b)=>a+b,0);
  const second = vals.slice(mid).reduce((a,b)=>a+b,0);
  if(first===0) return null;
  return Math.round(((second-first)/first)*100);
}
function fmt(n) { if(n===null||n===undefined) return '—'; return n>=1000?(n/1000).toFixed(1)+'k':String(n); }
function fmtDate(iso) {
  if(!iso) return '';
  const d = new Date(iso);
  return d.toLocaleDateString('es-ES',{day:'numeric',month:'short',year:'numeric'});
}
function trendColor(t) { if(t===null) return '#9ca3af'; return t>=0?'#22c55e':'#ef4444'; }
function trendArrow(t) { if(t===null) return '—'; return (t>=0?'↑ ':'↓ ')+Math.abs(t)+'%'; }
function borderColor(t) { if(t===null) return '#e5e7eb'; return t>=0?'#22c55e':'#ef4444'; }

const fbImpr = sum(fbRaw,'page_views_total');
const fbEng   = sum(fbRaw,'page_post_engagements');
const fbReacc = sum(fbRaw,'page_actions_post_reactions_total');
const fbNuevosFans = sum(fbRaw,'page_daily_follows_unique');
const fbFans  = (fbFanRaw && typeof fbFanRaw.fan_count === 'number') ? fbFanRaw.fan_count : null;
const fbImprT = halfTrend(fbRaw,'page_views_total');
const fbEngT  = halfTrend(fbRaw,'page_post_engagements');

const igImpr  = null; // 'impressions' no se pide a Meta desde el ítem 148 — nunca fue un dato real, se saca la tarjeta muerta
const igReach = sum(igRaw,'reach');
const igEng   = sum(igRaw,'accounts_engaged');
const igFoll  = (igFollowersRaw && typeof igFollowersRaw.followers_count === 'number') ? igFollowersRaw.followers_count : null;
const igViews = sum(igRaw,'profile_views');
const igClics = sum(igRaw,'website_clicks');
const igReachT= halfTrend(igRaw,'reach');
const igEngT  = halfTrend(igRaw,'accounts_engaged');
const igViewsT= halfTrend(igRaw,'profile_views');
const igClicsT= halfTrend(igRaw,'website_clicks');
const igEngRate = (igEng && igReach && igReach >= 10) ? Math.round((igEng/igReach)*1000)/10 : null;
const igMuestraChica = igReach !== null && igReach > 0 && igReach < 10;

const emp = empresa.data||empresa;
const companyName = emp.name||'Empresa';
const city = emp.base_city||'';
// Nunca cae a un email personal real como respaldo — mismo criterio de "cero fallbacks
// cruzados" ya establecido en el proyecto (ítem 171). Si la empresa no tiene ningún
// email configurado en G54, no hay destino: el envío se salta (ver emailConfigurado),
// nunca se manda a la bandeja personal de quien mantiene la plataforma.
const emailDest = (emp.emails||[])[0]||(reporte.email_cliente||'');
const emailConfigurado = !!emailDest;
const periodo = reporte.periodoLabel || new Date().toLocaleDateString('es-ES',{month:'long',year:'numeric'});
const recoText = reporte.recomendaciones||reporte.recommendations||'';
const recos = recoText.split(/\n/).map(r=>r.replace(/^[\d\.\-\*•\s]+/,'').replace(/\*\*/g,'').trim()).filter(r=>r.length>20).slice(0,6);

// ---- Clics al CTA del período — dato real ya recolectado por el tracker propio
// (ítem 213), leído de vuelta del mismo histórico de G54 que alimenta el resto del
// reporte. Antes se guardaba pero nunca se mostraba en ningún lado del reporte.
const clicsCtaTotal = metricasHistoricas.reduce((s,m)=>s+(m.clics_total||0), 0);

// ---- Salud de Contenido — posts publicados vs. comprometidos según la estrategia
// real (frecuencia × semanas del período), ya calculado en 🔧 Preparar Datos Analytics
// a partir de los posts reales de G54, filtrados al período real del reporte.
const totalPostsPeriodo = datosAnalytics.totalPosts || 0;
const totalComprometidos = datosAnalytics.totalComprometidos || 0;
const postsPorPlataforma = datosAnalytics.postsPorPlataforma || {};
const postsComprometidos = datosAnalytics.postsComprometidos || {};
const cumplioConsistencia = totalComprometidos > 0 ? (totalPostsPeriodo / totalComprometidos) : null;

// ---- Valor real generado — guardados/compartidos AGREGADOS del período completo,
// no solo de los últimos 3 posts mostrados en "Publicaciones recientes". Usa el
// timeline real de Meta (limit ampliado a 25, ítem de hoy) filtrado por la fecha
// real del período — no depende de post_id_platform de G54 (todavía sin persistir
// en ninguna publicación real, confirmado hoy).
function postInsight(p, name) {
  const arr = (p.insights && p.insights.data) || [];
  const m = arr.find(x => x.name === name);
  if (!m || !m.values || !m.values.length) return 0;
  const v = m.values[0].value;
  return typeof v === 'object' ? Object.values(v).reduce((a,b)=>a+(b||0),0) : (v||0);
}
function postFecha(p) { return new Date(p.created_time||p.timestamp||0).getTime(); }
const fechaInicioMs = (() => { try { return new Date($('⚙️ Config Growth54').first().json.FECHA_INICIO_UNIX*1000).getTime(); } catch(e){ return Date.now()-30*24*60*60*1000; } })();
const fechaFinMs = (() => { try { return new Date($('⚙️ Config Growth54').first().json.FECHA_FIN_UNIX*1000).getTime(); } catch(e){ return Date.now(); } })();
const periodPosts = [...fbPostsAll, ...igPostsAll].filter(p => {
  const t = postFecha(p);
  return t >= fechaInicioMs && t <= fechaFinMs;
});
const periodPostsConValor = periodPosts.map(p => {
  const isFb = p.plat === 'fb';
  const shares = isFb ? ((p.shares&&p.shares.count)||0) : postInsight(p,'shares');
  const saves = isFb ? 0 : postInsight(p,'saved');
  return { ...p, shares, saves, valorTotal: shares+saves };
});
const totalGuardados = periodPostsConValor.reduce((s,p)=>s+p.saves,0);
const totalCompartidos = periodPostsConValor.reduce((s,p)=>s+p.shares,0);
const promedioValor = periodPostsConValor.length > 0 ? (periodPostsConValor.reduce((s,p)=>s+p.valorTotal,0)/periodPostsConValor.length) : 0;
const postDestacado = periodPostsConValor.length > 0 ? periodPostsConValor.reduce((a,b)=> b.valorTotal > a.valorTotal ? b : a) : null;
const postDestacadoVeces = (postDestacado && promedioValor > 0) ? Math.round((postDestacado.valorTotal/promedioValor)*10)/10 : null;

function card(icon, val, trend, label, apiName) {
  const bc = borderColor(trend), tc = trendColor(trend), ta = trendArrow(trend);
  return `<table width="100%" cellpadding="0" cellspacing="0" style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;"><tr><td width="4" style="background:${bc};border-radius:10px 0 0 10px;font-size:0;">&nbsp;</td><td style="padding:12px 12px 10px;"><div style="font-size:15px;margin-bottom:3px;">${icon}</div><div style="font-size:22px;font-weight:800;color:#111827;line-height:1;">${fmt(val)}</div><div style="font-size:11px;font-weight:700;color:${tc};margin-top:2px;">${ta}</div><div style="font-size:9px;color:#9ca3af;margin-top:7px;text-transform:uppercase;letter-spacing:.05em;">${label}</div><div style="font-size:8px;color:#d1d5db;">${apiName}</div></td></tr></table>`;
}
function cardsRow(c1,c2,c3) {
  return `<table width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:10px;"><tr><td width="33%" style="padding-right:6px;vertical-align:top;">${c1}</td><td width="33%" style="padding:0 3px;vertical-align:top;">${c2}</td><td width="33%" style="padding-left:6px;vertical-align:top;">${c3}</td></tr></table>`;
}
function cardsRow2(c1,c2) {
  return `<table width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:10px;"><tr><td width="50%" style="padding-right:6px;vertical-align:top;">${c1}</td><td width="50%" style="padding-left:6px;vertical-align:top;">${c2}</td></tr></table>`;
}
function postRow(p) {
  const isFb=p.plat==='fb', platColor=isFb?'#1877F2':'#BC1888', platLabel=isFb?'Facebook':'Instagram';
  const bgThumb=isFb?'#e8f0fe':'#fce7f3', emoji=isFb?'📦':'📷';
  const caption=(p.message||p.caption||'').substring(0,120)+(((p.message||p.caption||'').length>120)?'…':'');
  const dt=fmtDate(p.created_time||p.timestamp);
  const likes=p.like_count!==undefined?p.like_count:(p.likes&&p.likes.summary?p.likes.summary.total_count:0);
  const comments=p.comments_count!==undefined?p.comments_count:(p.comments&&p.comments.summary?p.comments.summary.total_count:0);
  const shares = isFb ? ((p.shares&&p.shares.count)||0) : postInsight(p,'shares');
  const saves = isFb ? 0 : postInsight(p,'saved');
  const extraCell = isFb
    ? `<td style="font-size:10px;color:#9ca3af;padding-right:12px;">🔁 <strong style="color:#374151;">${shares}</strong></td>`
    : `<td style="font-size:10px;color:#9ca3af;padding-right:12px;">💾 <strong style="color:#374151;">${saves}</strong></td><td style="font-size:10px;color:#9ca3af;padding-right:12px;">🔁 <strong style="color:#374151;">${shares}</strong></td>`;
  return `<table width="100%" cellpadding="0" cellspacing="0" style="border-bottom:1px solid #f3f4f6;"><tr><td style="padding:10px 0;"><table width="100%" cellpadding="0" cellspacing="0"><tr><td width="52" style="vertical-align:top;padding-right:12px;"><div style="width:48px;height:48px;background:${bgThumb};border-radius:6px;text-align:center;line-height:48px;font-size:20px;">${emoji}</div></td><td style="vertical-align:top;"><span style="display:inline-block;background:${platColor};color:#fff;font-size:9px;font-weight:700;padding:2px 7px;border-radius:3px;text-transform:uppercase;margin-bottom:5px;">${platLabel}</span><div style="font-size:12px;color:#374151;line-height:1.5;">${caption||'(sin texto)'}</div><table cellpadding="0" cellspacing="0" style="margin-top:5px;"><tr><td style="font-size:10px;color:#9ca3af;padding-right:12px;">❤️ <strong style="color:#374151;">${likes}</strong></td><td style="font-size:10px;color:#9ca3af;padding-right:12px;">💬 <strong style="color:#374151;">${comments}</strong></td>${extraCell}<td style="font-size:10px;color:#d1d5db;">${dt}</td></tr></table></td></tr></table></td></tr></table>`;
}

// Tarjeta de resumen — mismo esqueleto visual que card() (borde de color, número
// grande, etiqueta chica) pero sin flecha de tendencia, con una línea de detalle
// real en su lugar. Se construyó así después de que la usuaria señalara que la
// primera versión (preguntas y párrafos sueltos) se veía desencajada frente al
// resto del reporte, que es 100% tarjetas — esto reusa el mismo lenguaje visual.
function summaryCard(icon, val, colorGood, label, detail) {
  const color = colorGood === true ? '#22c55e' : (colorGood === false ? '#ef4444' : '#9ca3af');
  return `<table width="100%" cellpadding="0" cellspacing="0" style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;"><tr><td width="4" style="background:${color};border-radius:10px 0 0 10px;font-size:0;">&nbsp;</td><td style="padding:12px 12px 10px;"><div style="font-size:15px;margin-bottom:3px;">${icon}</div><div style="font-size:22px;font-weight:800;color:#111827;line-height:1;">${val}</div><div style="font-size:9px;color:#9ca3af;margin-top:7px;text-transform:uppercase;letter-spacing:.05em;">${label}</div><div style="font-size:9px;color:#6b7280;margin-top:3px;">${detail}</div></td></tr></table>`;
}

// Divisor de etapa del funnel — más marcado que un header de bloque normal
// (fondo con tinte del azul de marca, no gris) para que se lea como una
// agrupación de nivel superior, no como una sección más entre las demás.
function stageHeader(label, sub) {
  return `<tr><td height="10" style="background:#eef0f4;font-size:0;">&nbsp;</td></tr>
<tr><td style="background:#eef2ff;border:1px solid #c7d2fe;border-radius:8px 8px 0 0;padding:11px 28px;">
  <table width="100%" cellpadding="0" cellspacing="0"><tr>
    <td style="font-size:11px;font-weight:800;color:#2D5BFF;text-transform:uppercase;letter-spacing:.09em;">${label}</td>
    ${sub ? `<td style="text-align:right;font-size:10px;color:#818cf8;">${sub}</td>` : ''}
  </tr></table>
</td></tr>`;
}

function buildResumenEjecutivo() {
  const consistenciaPct = totalComprometidos > 0 ? Math.round(cumplioConsistencia*100) : null;
  const consistenciaOk = totalComprometidos > 0 ? (cumplioConsistencia >= 1) : null;
  // Desglose por plataforma en el detalle — un total agregado (ej. "69%") puede
  // esconder que una plataforma cumplió al 100% y la otra al 0%. Se muestra cada
  // una por separado en vez de solo el número combinado.
  const plataformasConsistencia = Array.from(new Set([...Object.keys(postsPorPlataforma), ...Object.keys(postsComprometidos)]));
  const abrev = { Facebook: 'FB', Instagram: 'IG' };
  const consistenciaDetalle = totalComprometidos > 0
    ? plataformasConsistencia.map(pl => {
        const pub = postsPorPlataforma[pl] || 0, comp = postsComprometidos[pl] || 0;
        const pct = comp > 0 ? Math.round((pub/comp)*100) : 0;
        return `${abrev[pl]||pl}: ${pub}/${comp} (${pct}%)`;
      }).join(' · ')
    : 'Sin frecuencia definida en la estrategia';
  const consistenciaCard = summaryCard('📅', consistenciaPct!==null?consistenciaPct+'%':'—', consistenciaOk, 'Consistencia de publicación', consistenciaDetalle);

  const valorTotal = totalGuardados + totalCompartidos;
  // Referencia de escala real (seguidores) junto al valor absoluto — sin esto, "0
  // guardados" se lee igual para una cuenta de 300 seguidores que para una de 30,000.
  // No inventa un "promedio de la industria", solo da la escala real de la cuenta.
  const seguidoresTotal = (fbFans||0) + (igFoll||0);
  const valorDetalle = periodPostsConValor.length > 0
    ? `${totalGuardados} guardados, ${totalCompartidos} compartidos en ${periodPostsConValor.length} publicaciones${(postDestacado && postDestacadoVeces && postDestacadoVeces > 1.3) ? ` — la mejor tuvo ${postDestacadoVeces}x el promedio` : ''}${seguidoresTotal>0?` · ${seguidoresTotal} seguidores en total`:''}`
    : 'Sin publicaciones reales de Meta este período';
  const valorCard = summaryCard('💎', valorTotal, periodPostsConValor.length===0?null:(valorTotal>0), 'Guardados + compartidos', valorDetalle);

  const totalLeads = datosAnalytics.totalLeads || 0;
  const leadsCalientes = datosAnalytics.leadsCalientes || 0;
  const demandaCard = summaryCard('📥', totalLeads, totalLeads>0, 'Leads generados', `${leadsCalientes} calificados/calientes`);

  // Hecho operativo real (no una recomendación) — si hay contenido ya aprobado o en
  // borrador sin publicar, es una causa verificable de una consistencia baja, sin
  // opinar sobre qué hacer al respecto.
  const aprobados = datosAnalytics.postsAprobadosSinProgramar || 0;
  const borradores = datosAnalytics.postsBorrador || 0;
  const backlogPartes = [];
  if (aprobados > 0) backlogPartes.push(`${aprobados} post${aprobados===1?'':'s'} aprobado${aprobados===1?'':'s'} sin programar`);
  if (borradores > 0) backlogPartes.push(`${borradores} en borrador`);
  const backlogNota = backlogPartes.length > 0
    ? `<div style="font-size:10px;color:#6b7280;margin-top:10px;padding-top:8px;border-top:1px solid #e5e7eb;">📋 Estado actual: ${backlogPartes.join(' · ')}.</div>`
    : '';

  return `<tr><td style="background:#f9fafb;border:1px solid #e5e7eb;border-top:none;padding:9px 28px;">
  <table width="100%" cellpadding="0" cellspacing="0"><tr>
    <td style="font-size:10px;font-weight:700;color:#9ca3af;text-transform:uppercase;letter-spacing:.08em;">🧭 Resumen Ejecutivo</td>
    <td style="text-align:right;font-size:10px;color:#d1d5db;">consistencia · valor · demanda</td>
  </tr></table>
</td></tr>
<tr><td style="background:#f9fafb;border:1px solid #e5e7eb;border-top:none;padding:12px 22px 16px;">
  ${cardsRow(consistenciaCard, valorCard, demandaCard)}
  ${backlogNota}
</td></tr>`;
}

function buildSaludContenidoBlock() {
  if (totalComprometidos === 0) return '';
  const plataformas = Array.from(new Set([...Object.keys(postsPorPlataforma), ...Object.keys(postsComprometidos)]));
  const rows = plataformas.map(pl => `<tr>
    <td style="padding:5px 0;border-bottom:1px solid #f3f4f6;font-size:12px;color:#4b5563;">${pl}</td>
    <td style="padding:5px 0;border-bottom:1px solid #f3f4f6;font-size:12px;color:#111827;font-weight:700;text-align:right;">${postsPorPlataforma[pl]||0} de ${postsComprometidos[pl]||0}</td>
  </tr>`).join('');
  return `<tr><td style="background:#f9fafb;border:1px solid #e5e7eb;border-top:none;padding:9px 28px;">
  <table width="100%" cellpadding="0" cellspacing="0"><tr>
    <td style="font-size:10px;font-weight:700;color:#9ca3af;text-transform:uppercase;letter-spacing:.08em;">📋 Salud de Contenido <span style="text-transform:none;font-weight:400;">(diagnóstico, no resultado)</span></td>
  </tr></table>
</td></tr>
<tr><td style="background:#f9fafb;border:1px solid #e5e7eb;border-top:none;padding:6px 28px 16px;">
  <table width="100%" cellpadding="0" cellspacing="0">
    <tr><td style="font-size:10px;color:#9ca3af;text-transform:uppercase;padding-bottom:4px;">Plataforma</td><td style="font-size:10px;color:#9ca3af;text-transform:uppercase;text-align:right;padding-bottom:4px;">Publicados / Comprometidos</td></tr>
    ${rows}
  </table>
  <div style="font-size:9px;color:#9ca3af;margin-top:8px;">* Comprometidos = frecuencia de la estrategia × semanas del período. Este dato explica el contexto de los resultados, no es el resultado en sí.</div>
</td></tr>`;
}

function buildProgresoBlock(lb, hoy, ventasPorCanal, hitos) {
  if (!lb) return '';
  const fecha = lb.fecha ? new Date(lb.fecha + 'T00:00:00').toLocaleDateString('es-NI', {day:'numeric', month:'long', year:'numeric'}) : '';
  function deltaLabel(actual, base) {
    const diff = actual - base;
    if (diff > 0) return { txt: '▲ +' + fmt(diff) + ' desde el inicio', cls: 'up' };
    if (diff < 0) return { txt: '▼ ' + fmt(diff) + ' desde el inicio', cls: 'down' };
    return { txt: '— sin cambio', cls: 'flat' };
  }
  function progresoCard(icon, val, base, label) {
    const d = deltaLabel(val, base);
    const bc = d.cls === 'up' ? '#22c55e' : (d.cls === 'down' ? '#ef4444' : '#e5e7eb');
    const tc = d.cls === 'up' ? '#22c55e' : (d.cls === 'down' ? '#ef4444' : '#9ca3af');
    return `<table width="100%" cellpadding="0" cellspacing="0" style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;"><tr><td width="4" style="background:${bc};border-radius:10px 0 0 10px;font-size:0;">&nbsp;</td><td style="padding:12px 12px 10px;"><div style="font-size:15px;margin-bottom:3px;">${icon}</div><div style="font-size:22px;font-weight:800;color:#111827;line-height:1;">${fmt(val)}</div><div style="font-size:11px;font-weight:700;color:${tc};margin-top:2px;">${d.txt}</div><div style="font-size:9px;color:#9ca3af;margin-top:7px;text-transform:uppercase;letter-spacing:.05em;">${label}</div><div style="font-size:8px;color:#d1d5db;">Línea base: ${fmt(base)}</div></td></tr></table>`;
  }
  const base1 = lb.leads_total_conversaciones || 0;
  const base2 = lb.engagement_total || 0;
  const base3 = lb.deals_total || 0;
  const c1 = progresoCard('💬', hoy.leads, base1, 'Leads generados');
  const c2 = progresoCard('❤️', hoy.engagement, base2, 'Interacciones (engagement)');
  const c3 = progresoCard('💼', hoy.deals, base3, 'Negocios en el CRM');
  const todoIgual = hoy.leads === base1 && hoy.engagement === base2 && hoy.deals === base3;
  const nota = todoIgual
    ? `<div style="font-size:10.5px;color:#9ca3af;margin-top:8px;">* Esta es la primera medición desde que arrancó la línea base — todavía no pasó suficiente tiempo para ver un cambio real.</div>`
    : '';
  function moneyCard(icon, val, base, label) {
    const diff = val - base;
    const bc = diff > 0 ? '#22c55e' : (diff < 0 ? '#ef4444' : '#e5e7eb');
    const tc = diff > 0 ? '#22c55e' : (diff < 0 ? '#ef4444' : '#9ca3af');
    const txt = diff > 0 ? ('▲ +$' + fmt(diff)) : (diff < 0 ? ('▼ $' + fmt(diff)) : '— sin cambio');
    return `<table width="100%" cellpadding="0" cellspacing="0" style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;margin-bottom:10px;"><tr><td width="4" style="background:${bc};border-radius:10px 0 0 10px;font-size:0;">&nbsp;</td><td style="padding:14px 16px 12px;"><div style="font-size:15px;margin-bottom:3px;">${icon}</div><div style="font-size:28px;font-weight:800;color:#111827;line-height:1;">$${fmt(val)}</div><div style="font-size:12px;font-weight:700;color:${tc};margin-top:2px;">${txt}</div><div style="font-size:9.5px;color:#9ca3af;margin-top:7px;text-transform:uppercase;letter-spacing:.05em;">${label}</div></td></tr></table>`;
  }

  function canalBreakdownHtml(porCanal) {
    const claves = Object.keys(porCanal || {}).filter(k => porCanal[k] > 0);
    if (claves.length === 0) return '';
    const origenLabel = { facebook:'Facebook', instagram:'Instagram', rrss:'Redes sociales', whatsapp:'WhatsApp', direct:'WhatsApp', manual:'Contacto manual', web:'Sitio web' };
    const filas = claves.map(k => `<tr><td style="padding:2px 0;font-size:10.5px;color:#6b7280;">${origenLabel[k]||k}</td><td style="padding:2px 0;font-size:10.5px;color:#111827;font-weight:700;text-align:right;">${fmt(porCanal[k])}</td></tr>`).join('');
    return `<table width="100%" cellpadding="0" cellspacing="0" style="margin-top:6px;margin-bottom:10px;">${filas}</table>`;
  }

  const cMoney = moneyCard('💵', hoy.ventasCerradas || 0, lb.ventas_cerradas || 0, 'Ventas cerradas');
  const canalHtml = canalBreakdownHtml(ventasPorCanal);
  const hitosHtml = hitos ? `<div style="font-size:10px;color:#6b7280;margin-top:8px;padding-top:8px;border-top:1px solid #f3f4f6;"><strong>Hitos de arranque:</strong> primer lead real ${hitos.dias_a_primer_lead !== null ? 'a los ' + hitos.dias_a_primer_lead + ' día(s)' : 'aún no llega'} · primera venta real ${hitos.dias_a_primera_venta !== null ? 'a los ' + hitos.dias_a_primera_venta + ' día(s)' : 'aún no llega'}</div>` : '';
  return `<tr><td style="background:#f9fafb;border:1px solid #e5e7eb;border-top:none;padding:9px 28px;">
  <table width="100%" cellpadding="0" cellspacing="0"><tr>
    <td style="font-size:10px;font-weight:700;color:#9ca3af;text-transform:uppercase;letter-spacing:.08em;">📈 Progreso desde el inicio</td>
    <td style="text-align:right;font-size:10px;color:#d1d5db;">línea base: ${fecha}</td>
  </tr></table>
</td></tr>
<tr><td style="background:#fff;border:1px solid #e5e7eb;border-top:none;padding:12px 24px 14px;">
  ${cMoney}
  ${canalHtml}
  ${cardsRow(c1, c2, c3)}
  ${nota}
  ${hitosHtml}
</td></tr>`;
}

// Post-venta / Retención — antes vivía embebido adentro de "Progreso desde el
// inicio"; se separó en su propia etapa del funnel (post-venta) porque mezclar
// "cuánto vendimos" con "cuántos vuelven a comprar" bajo el mismo bloque
// escondía que son preguntas distintas del negocio.
function buildRetencionBlock(retencion) {
