  const ltvTxt = (retencion.ltvPromedio !== null && retencion.ltvPromedio !== undefined) ? ('$' + fmt(retencion.ltvPromedio)) : '— sin ventas reales aún';
  return `<tr><td style="background:#f9fafb;border:1px solid #e5e7eb;border-top:none;padding:9px 28px;">
  <table width="100%" cellpadding="0" cellspacing="0"><tr>
    <td style="font-size:10px;font-weight:700;color:#9ca3af;text-transform:uppercase;letter-spacing:.08em;">🔁 Retención y costo de adquisición</td>
  </tr></table>
</td></tr>
