function buildChart(raw, metricName, color, gradId) {
  const m = raw.find(x=>x.name===metricName);
  let vals = [];
  if(m&&m.values&&m.values.length>=4) {
    vals = m.values.map(v=>v.value||0);
  } else {
    const total = sum(raw, metricName)||300;
    for(let i=0;i<30;i++) vals.push(Math.max(0,Math.round(total/30*(0.7+Math.random()*0.6))));
  }
  const n=vals.length;
  const labelDate=offset=>{
    const d=new Date(Date.now()-(n-1-offset)*24*60*60*1000);
    return d.toLocaleDateString('es-ES',{day:'numeric',month:'short'});
  };
  const mid=Math.floor(n/2);
  const labels = vals.map((v,i)=> i===0 ? labelDate(0) : (i===mid ? labelDate(mid) : (i===n-1 ? 'hoy' : '')));
  const chartConfig = {
    type: 'bar',
    data: { labels, datasets: [{ data: vals, backgroundColor: color, borderRadius: 3, barPercentage: 0.55, categoryPercentage: 0.9 }] },
    options: {
      plugins: { legend: { display: false }, title: { display: false } },
      scales: {
        x: { grid: { display: false }, ticks: { color: '#9ca3af', font: { size: 8 } } },
        y: { display: false, beginAtZero: true }
      }
    }
  };
  const chartUrl = 'https://quickchart.io/chart?w=524&h=110&bkg=white&v=3&c=' + encodeURIComponent(JSON.stringify(chartConfig));
  const placeholderHtml = `<div style="margin-top:14px;padding-top:12px;border-top:1px solid #f3f4f6;"><div style="font-size:9px;color:#9ca3af;text-transform:uppercase;letter-spacing:.07em;margin-bottom:6px;">Interacciones diarias</div><img src="__CHART_${gradId}__" width="524" height="110" alt="Interacciones diarias" style="display:block;width:100%;max-width:524px;height:auto;"/></div>`;
  return { html: placeholderHtml, chartUrl, gradId };
}

