async function leerYParsear(rows, modoBuscado) {
  const candidatos = rows.filter(r => r.modo === modoBuscado);
  candidatos.sort((a, b) => new Date(b.periodo_inicio) - new Date(a.periodo_inicio));
  if (candidatos.length === 0) return null;
  const detalle = await this.helpers.httpRequest({
    method: 'GET',
    url: baseUrl + '/api/rrss/reportes/' + candidatos[0].id,
    headers: { Authorization: 'Bearer ' + token },
    json: true,
  });
  const html = (detalle && detalle.data && detalle.data.html) || '';
  const m = html.match(/LINEA_BASE_JSON:\s*(\{.*?\})\s*-->/);
  return m ? JSON.parse(m[1]) : null;
}

try {
  const listResp = await this.helpers.httpRequest({
    method: 'GET',
    url: baseUrl + '/api/rrss/reportes?company_id=' + companyId,
    headers: { Authorization: 'Bearer ' + token },
    json: true,
  });
  const rows = (listResp && listResp.data) || [];
  lineaBase = await leerYParsear.call(this, rows, 'linea_base');
  lineaBaseEvento = await leerYParsear.call(this, rows, 'linea_base_evento');
} catch (e) {
  // sin línea base disponible — las secciones simplemente no se muestran
}

let boardCompleto = null;
// KPI #2 (mitad real, sin CAC): LTV real por cliente — suma de ventas cerradas reales
// (nunca estimadas de una etapa que no llegó a cerrar) agrupadas por identidad real del
// cliente (wa_contact_id, o teléfono si no hay contacto de WA vinculado). Un cliente con
// más de 1 venta cerrada es un cliente recurrente real, no una suposición.
const ventasPorClienteHoy = new Map(); // clave real del cliente -> {total, ventas}
try {
  const board = await this.helpers.httpRequest({
    method: 'GET',
    url: baseUrl + '/api/crm/board',
    headers: { Authorization: 'Bearer ' + token },
    json: true,
  });
  if (board && typeof board === 'object') {
    boardCompleto = board;
    for (const [etapa, v] of Object.entries(board)) {
      if (!Array.isArray(v)) continue;
      dealsHoy += v.length;
      if (etapa === 'closed') {
        for (const d of v) {
          const monto = Number(d.valor_estimado) || 0;
          ventasCerradasHoy += monto;
          // origen real del deal (whatsapp/facebook/instagram/manual/web/...) — mismo
          // campo que ya usa el resto de la plataforma para atribuir un lead a su canal
          const canal = d.origen || 'sin_origen';
          ventasPorCanalHoy[canal] = (ventasPorCanalHoy[canal] || 0) + monto;

          if (monto > 0) {
            const claveCliente = d.wa_contact_id ? ('wa_' + d.wa_contact_id) : (d.telefono ? ('tel_' + d.telefono) : ('deal_' + d.id));
            const acc = ventasPorClienteHoy.get(claveCliente) || { total: 0, ventas: 0 };
            acc.total += monto;
            acc.ventas += 1;
            ventasPorClienteHoy.set(claveCliente, acc);
          }
        }
      }
    }
  }
} catch (e) {
  // sin datos de CRM disponibles — se compara solo lo que sí se pudo leer
}

const clientesConVentaReal = ventasPorClienteHoy.size;
const clientesRecurrentes = Array.from(ventasPorClienteHoy.values()).filter(c => c.ventas > 1).length;
const ltvPromedio = clientesConVentaReal > 0
  ? Math.round(Array.from(ventasPorClienteHoy.values()).reduce((a, c) => a + c.total, 0) / clientesConVentaReal)
  : null;

// Hitos de arranque (KPI #5 — transferencia entre proyectos): días reales desde que se
// capturó la línea base hasta el primer lead real y hasta la primera venta real. Esto
// no compara todavía contra otro proyecto (para eso hace falta una vista aparte,
// cross-empresa) — hoy solo captura el dato crudo de ESTA empresa, con fecha real,
// para que esa comparación futura tenga datos genuinos en vez de inventados.
let hitos = null;
if (lineaBase && lineaBase.fecha) {
  const fechaLB = new Date(lineaBase.fecha);
  let primerLeadFecha = null;
  try {
    const conv = await this.helpers.httpRequest({
      method: 'GET',
      url: baseUrl + '/api/whatsapp/conversations?per_page=200',
      headers: { Authorization: 'Bearer ' + token },
      json: true,
    });
    const todos = (conv && conv.data) || [];
    const posterioresALineaBase = todos
      .filter(c => c.created_at && new Date(c.created_at) >= fechaLB)
      .sort((a, b) => new Date(a.created_at) - new Date(b.created_at));
    if (posterioresALineaBase.length > 0) primerLeadFecha = posterioresALineaBase[0].created_at;
  } catch (e) {}

  let primeraVentaFecha = null;
  if (boardCompleto && Array.isArray(boardCompleto.closed)) {
    const cerradosPosteriores = boardCompleto.closed
      .filter(d => d.updated_at && new Date(d.updated_at) >= fechaLB && Number(d.valor_estimado) > 0)
      .sort((a, b) => new Date(a.updated_at) - new Date(b.updated_at));
    if (cerradosPosteriores.length > 0) primeraVentaFecha = cerradosPosteriores[0].updated_at;
  }

  const diasDesde = (fechaStr) => fechaStr ? Math.max(0, Math.round((new Date(fechaStr) - fechaLB) / 86400000)) : null;
  hitos = {
    fecha_linea_base: lineaBase.fecha,
    primer_lead_fecha: primerLeadFecha,
    dias_a_primer_lead: diasDesde(primerLeadFecha),
    primera_venta_fecha: primeraVentaFecha,
    dias_a_primera_venta: diasDesde(primeraVentaFecha),
  };
}

return [{ json: {
  lineaBase, lineaBaseEvento, dealsHoy, ventasCerradasHoy, ventasPorCanalHoy, hitos,
  clientesConVentaReal, clientesRecurrentes, ltvPromedio
} }];

const cfg = $('⚙️ Config Growth54').first().json;
const baseUrl = cfg.G54_BASE_URL;
const agentToken = cfg.G54_AGENT_TOKEN;
const companyIdActual = Number(cfg.G54_COMPANY_ID);

let hitosOtrasEmpresas = [];

async function leerLineaBase(baseUrl, token, companyId) {
  const listResp = await this.helpers.httpRequest({
    method: 'GET',
    url: baseUrl + '/api/rrss/reportes?company_id=' + companyId,
    headers: { Authorization: 'Bearer ' + token },
    json: true,
  });
  const rows = (listResp && listResp.data) || [];
  const candidatos = rows.filter(r => r.modo === 'linea_base');
  candidatos.sort((a, b) => new Date(b.periodo_inicio) - new Date(a.periodo_inicio));
  if (candidatos.length === 0) return null;
  const detalle = await this.helpers.httpRequest({
    method: 'GET',
    url: baseUrl + '/api/rrss/reportes/' + candidatos[0].id,
    headers: { Authorization: 'Bearer ' + token },
    json: true,
  });
  const html = (detalle && detalle.data && detalle.data.html) || '';
  const m = html.match(/LINEA_BASE_JSON:\s*(\{.*?\})\s*-->/);
  return m ? JSON.parse(m[1]) : null;
}

try {
  // Listado de empresas activas — con AGENT_TOKEN, sin necesitar sesión
  const companiesResp = await this.helpers.httpRequest({
    method: 'GET',
    url: baseUrl + '/api/n8n/companies',
    headers: { Authorization: 'Bearer ' + agentToken },
    json: true,
  });
  const otras = ((companiesResp && companiesResp.data) || [])
    .filter(c => c.is_active && Number(c.id) !== companyIdActual);

  if (otras.length > 0) {
    // Login propio y aislado — nunca toca la sesión que usa el resto de este reporte
    const login = await this.helpers.httpRequest({
      method: 'POST',
      url: baseUrl + '/api/auth/login',
      body: { email: 'master@growth54.local', password: 'REDACTED_MASTER_PASSWORD' },
      json: true,
    });
    const token = login.access_token;

    for (const empresa of otras) {
      try {
        await this.helpers.httpRequest({
          method: 'POST',
          url: baseUrl + '/api/auth/switch-company',
          body: { company_id: empresa.id },
          headers: { Authorization: 'Bearer ' + token },
          json: true,
        });

        const lineaBaseOtra = await leerLineaBase.call(this, baseUrl, token, empresa.id);
        if (!lineaBaseOtra || !lineaBaseOtra.fecha) continue;

        const fechaLB = new Date(lineaBaseOtra.fecha);

        let primerLeadFecha = null;
        try {
          const conv = await this.helpers.httpRequest({
            method: 'GET',
            url: baseUrl + '/api/whatsapp/conversations?per_page=200',
            headers: { Authorization: 'Bearer ' + token },
            json: true,
          });
          const todos = (conv && conv.data) || [];
          const posteriores = todos
            .filter(c => c.created_at && new Date(c.created_at) >= fechaLB)
            .sort((a, b) => new Date(a.created_at) - new Date(b.created_at));
          if (posteriores.length > 0) primerLeadFecha = posteriores[0].created_at;
        } catch (e) {}

        let primeraVentaFecha = null;
        try {
          const board = await this.helpers.httpRequest({
            method: 'GET',
            url: baseUrl + '/api/crm/board',
            headers: { Authorization: 'Bearer ' + token },
            json: true,
          });
          if (board && Array.isArray(board.closed)) {
            const cerradosPosteriores = board.closed
              .filter(d => d.updated_at && new Date(d.updated_at) >= fechaLB && Number(d.valor_estimado) > 0)
              .sort((a, b) => new Date(a.updated_at) - new Date(b.updated_at));
            if (cerradosPosteriores.length > 0) primeraVentaFecha = cerradosPosteriores[0].updated_at;
          }
        } catch (e) {}

        const diasDesde = (fechaStr) => fechaStr ? Math.max(0, Math.round((new Date(fechaStr) - fechaLB) / 86400000)) : null;

        hitosOtrasEmpresas.push({
          company_id: empresa.id,
          nombre: empresa.name,
          hitos: {
            fecha_linea_base: lineaBaseOtra.fecha,
            primer_lead_fecha: primerLeadFecha,
            dias_a_primer_lead: diasDesde(primerLeadFecha),
            primera_venta_fecha: primeraVentaFecha,
            dias_a_primera_venta: diasDesde(primeraVentaFecha),
          },
        });
      } catch (e) {
        // esta empresa en particular falló — se sigue con las demás, sin cortar el reporte
      }
    }
  }
} catch (e) {
  // sin comparación disponible — la sección simplemente no se muestra
}

return [{ json: { hitosOtrasEmpresas } }];
